-- 01 crea disc_model_owner.macro_apoyo_ticker (maestra, 78 tickers)
CREATE TABLE disc_model_owner.macro_apoyo_ticker
WITH (format = 'PARQUET', write_compression = 'SNAPPY') AS
SELECT CAST(ticker AS VARCHAR) AS ticker,
       CAST(nro_variable AS VARCHAR) AS nro_variable,
       CAST(familia AS VARCHAR) AS familia,
       CAST(escenario AS VARCHAR) AS escenario,
       CAST(nom_variable AS VARCHAR) AS nom_variable,
       CAST(unidad AS VARCHAR) AS unidad,
       CAST(ticker_bcrp1 AS VARCHAR) AS ticker_bcrp1,
       CAST(ticker_bcrp2 AS VARCHAR) AS ticker_bcrp2,
       CAST(equivalencia_bcrp AS VARCHAR) AS equivalencia_bcrp,
       CAST(nota_bcrp AS VARCHAR) AS nota_bcrp
